-- DQ-011: Histology and HER2 Status Consistency---- Purpose:-- Validate the distribution of HER2.Final.Status within each-- histological subtype in the staging layer.---- This validation checks whether the cross-tabulation-- preserves the complete staging population.---- Expected total:-- - 705 records---- This validation does not modify the data.SELECT    "histological.type",    "HER2.Final.Status",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY    "histological.type",    "HER2.Final.Status"ORDER BY    "histological.type",    quantity DESC;